INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('f33a72bc-44fd-4b8a-8260-9ff3f60683d1', 'A/B Split bot', 'in_house', 'Most A/B tests are invisible.
<BR><BR>
Visitors land, see nothing, leave — and you''re left guessing which headline actually converted.
<BR><BR>
AB Split Bot flips the model entirely. Instead of running a silent test in the background, the test becomes a part of the offer!
<BR><BR>
Visitors see two variants, tap to choose their favorite, and unlock a 10% discount for participating.
<BR><BR>
Stack a second choice and they unlock 20%. The discount appears only after they engage — so it feels earned, not desperate.
<BR><BR>
Meanwhile, every view, vote, and conversion is logged in your dashboard with real statistical confidence. You get conversion lift and genuine preference data at the same time.
<BR><BR>
Works on any site with no plugin required. Built-in affiliate tracking means partners can promote any live test with their own slug and earn on every conversion.', NULL, 'https://absplitbot.com', '{"Conversion Optimization","A/B Testing","CRO","Engagement"}', NULL, '{"A/B testing","split testing","conversion rate optimization","CRO","visitor engagement","interactive testing","discount trigger","conversion lift","preference data","headline testing","copy testing","offer testing","visitor voting","engagement widget","conversion widget","discount unlock","interactive discount","split test tool","no-code testing","website optimization","landing page testing","sales page testing","conversion tracking","statistical significance","affiliate testing","split test widget"}', '$0 to $27/month', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/61b71e99-38a5-42a4-a090-ebdec67d19a9.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('922b6410-5380-4478-97a2-23f093181c5c', 'Doodle Rocket', 'in_house', 'The gap between a great idea and a finished piece of content has never been about creativity — it''s always been about execution.
<BR><BR>
Doodle Rocket closes that gap.
<BR><BR>
Start with a rough concept, a quick sketch, or a half-formed thought, and Doodle Rocket transforms it into clickable, shareable content without requiring design skills, a production budget, or a four-hour tutorial.
<BR><BR>
Built for solo creators, affiliate marketers, and small teams who need to ship content consistently without getting stuck in the production bottleneck.
<BR><BR>
Choose a template, drop in your concept, customize the basics, and launch.
<BR><BR>
That''s it. No design degree required. No expensive software. No waiting on a designer.
<BR><BR>
Whether it''s a lead magnet, a social graphic, or a promotional asset, Doodle Rocket gets your idea off the whiteboard and in front of an audience — fast.', NULL, 'https://doodlerocket.com', '{"Content Creation","Design","Visual Content","No-Code"}', NULL, '{"content creation","visual content","no-code design","graphic creation","lead magnets","social graphics","promotional assets","content templates","idea to content","quick design","non-designer tools","content for non-designers","visual marketing","graphic templates","content launch","fast content","simple design tool","content without design skills","marketing graphics","social media graphics","blog graphics","ad creatives","content ideation","visual storytelling","content production"}', '$0 to $97/month', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/2d2241f9-d73c-455f-aa73-ebfe116fe091.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('5bc24967-5f2e-4ee9-93c7-e6753f8ff862', 'Affiliate Program Pro', 'in_house', 'Finding the right affiliate programs used to mean hours of manual searching, dead links, and programs that barely convert.

Affiliate Program Pro replaces all of that with an AI-powered discovery engine that finds high-quality programs in any niche in minutes.

Search by keyword, category, or commission type — then store everything that looks promising in your private vault for review, comparison, and activation.

No more scattered bookmarks. No more lost programs buried in browser history. Your vault is organized, searchable, and accessible whenever you need it.

Whether you''re building a new niche site, expanding an existing portfolio, or researching programs for a client, Affiliate Program Pro gives you a structured system for the part of affiliate marketing most people still do manually.

Find more programs. Miss fewer opportunities. Keep everything in one place.', NULL, 'https://affiliateprogrampro.com', '{"Affiliate Marketing","Program Discovery","Monetization"}', NULL, '{"affiliate programs","affiliate marketing","affiliate discovery","affiliate vault","program finder","commission research","affiliate research","monetization","affiliate management","program database","niche affiliate programs","high commission programs","recurring commissions","affiliate income","program comparison","affiliate organization","affiliate bookmarks","affiliate tracking","program vetting","affiliate strategy","passive income","affiliate tools","program search","commission rates","affiliate network","JV programs","partner programs","referral programs"}', '$0 to $37 brandable version (one-time fee)', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/df0db3e3-aad7-4d2a-b414-d78a1773762a.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('6db525c0-6866-4ba1-ba3f-af48d53d3718', 'BYOT bot', 'in_house', 'Stop paying for tools that charge you just to talk to your own customers.
<BR><BR>
BYOT Bot gives you 30 pre-built communication and automation tools in one centralized dashboard — and all you need to activate them is your own Twilio account.
<BR><BR>
SMS campaigns, voice workflows, alerts, follow-up sequences, lead notifications — it''s all already built.
<BR><BR>
You just connect your Twilio credentials and start using them. No proprietary messaging fees. No middleman marking up your usage.
<BR><BR>
You pay Twilio directly at their rates and keep every penny of the difference. Thirty tools. One dashboard.
<BR><BR>
Your account, your data, your costs. Whether you''re running a single campaign or managing communication across multiple funnels, BYOT Bot gives you enterprise-level capability without the enterprise-level price tag.
<BR><BR>
Bring your Twilio. We''ll handle the rest.', NULL, 'https://byotbot.com', '{"SMS Marketing","Communication Automation","Twilio","Messaging"}', NULL, '{"Twilio","SMS marketing","text message marketing","SMS automation","voice workflows","lead notifications","follow-up sequences","SMS campaigns","communication tools","messaging automation","bulk SMS","text alerts","appointment reminders","lead follow-up","SMS broadcasts","two-way texting","phone automation","Twilio tools","bring your own Twilio","SMS dashboard","communication dashboard","text message campaigns","automated texting","SMS drip","business texting","customer communication","mobile marketing"}', 'TBD', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/0b125eb9-315f-4117-b16b-f441e6ef98b9.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('f66016eb-3686-4a23-bed4-a8ea4d27cde3', 'Vault Stacker', 'in_house', 'Vault Stacker is the content production tool built for operators who treat articles like infrastructure — not a one-off side hustle.
<BR><BR>
Connect your own ChatGPT API key, define a batch, and generate dozens of SEO-ready articles organized by category, slug, and topic cluster in a single run.
<BR><BR>
There''s no markup on your API usage — you pay OpenAI directly and keep every penny of the difference.
<BR><BR>
Schedule drops on your cadence, build topical authority across your niche, and export your entire vault as a clean .zip whenever you need it.
<BR><BR>
Articles live in your vault, your storage, your CMS. Vault Stacker doesn''t republish, syndicate, or touch your content after delivery. You own everything. Built for solo SEOs, niche site builders, and content-heavy affiliate operators ready to scale.', NULL, 'https://vaultstacker.com', '{"Content Creation","SEO","AI Writing","WordPress"}', NULL, '{"bulk content creation","AI article writing","SEO content","content batching","niche site content","topical authority","content scaling","WordPress publishing","ChatGPT content","BYOA","bring your own API","content vault","article generation","blog automation","content scheduling","SEO articles","niche sites","affiliate content","content clusters","topic clusters","keyword content","mass content","content production","content infrastructure","automated blogging","AI SEO","content factory","bulk publishing"}', '$27 to $47/month', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/e3fd5979-2665-4a48-bf72-d1663235efd8.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('233b3b8e-c6e7-4555-8eb1-f27d72e8048e', 'Hover CTRL', 'in_house', 'Every app you use is loaded with shortcuts.
<BR><BR>
Almost nobody uses them — not because they don''t want to, but because nobody can remember 200 keyboard combinations while they''re in the middle of actual work.
<BR><BR>
Hover CTRL solves that permanently. A floating shortcut widget sits on top of every application, always visible, always one click away.
<BR><BR>
Hover over any command to see the shortcut. Click to execute it without breaking your flow. Customize your most-used shortcuts into a personal panel that matches how you actually work.
<BR><BR>
Works across applications — your browser, your editor, your design tools, your CRM. No more hunting through menus. No more forgotten hotkeys slowing you down.
<BR><BR>
The faster you move through your tools, the more you accomplish. Hover CTRL makes fast operators faster — and gets everyone else there sooner.', NULL, 'https://hoverctrl.com', '{"Productivity","Keyboard Shortcuts","Workflow","Desktop Tools"}', NULL, '{"keyboard shortcuts","productivity tool","workflow optimization","hotkeys","shortcut manager","floating widget","always on top","desktop productivity","keyboard efficiency","shortcut reference","workflow speed","productivity software","keyboard mastery","shortcut cheat sheet","command reference","app shortcuts","browser shortcuts","design shortcuts","editor shortcuts","CRM shortcuts","productivity hacks","time saving tools","keyboard commands","shortcut overlay","workflow tools"}', '$17/month to $297 life-time, one-time fee', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/18f8bf99-1e03-4cef-b633-f9178db3e987.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('0886733f-78c9-4156-ae48-8547ad4620ef', 'Duet Cut', 'in_house', 'Portrait video for Reels. Landscape video for YouTube.
<BR><BR>
Two formats, one piece of content — and traditionally, two completely separate edit sessions.
<BR><BR>
Duet Cut eliminates the double work. Drop in your portrait clip and your landscape clip, and Duet Cut automatically height-matches both videos so they sit side by side in perfect alignment.
<BR><BR>
No manual resizing. No timeline juggling. No frame-by-frame adjustments. Three clicks and you have a finished side-by-side export ready to post, embed, or share.
<BR><BR>
Built for creators who publish across multiple platforms and can''t afford to spend twice as long editing just to satisfy two different aspect ratios.
<BR><BR>
Clean, fast, single-purpose. Duet Cut doesn''t try to be a full video editor — it does one thing, does it perfectly, and gets out of your way. That''s the whole product.', NULL, 'https://duetcut.com', '{"Video Editing","Content Repurposing","Multi-Platform","Social Media"}', NULL, '{"video editing","side by side video","portrait video","landscape video","dual format video","content repurposing","Reels editing","YouTube editing","TikTok editing","multi-platform video","video export","no-timeline editing","simple video editor","video height matching","dual aspect ratio","social media video","video production","content creator tools","video workflow","fast video editing","one-click export","video formatting","vertical video","horizontal video","video repurposing tool"}', 'Credits packages available starting at $5.00', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/47ddb7e8-efd0-4cb7-9f89-1d54f6cd0f9e.png', true);
INSERT INTO fixes (id, name, type, summary, description, url, categories, platforms, tags, price_note, image_url, active) VALUES ('e0242da0-b625-47bd-9d53-888fbf7db4b5', 'VEO Accelerator', 'in_house', 'TubeBuddy helps you get views. VEO Accelerator helps you get cited!
<BR><BR>
AI engines are answering questions your videos should be winning — and most creators have no idea it''s even happening.
<BR><BR>
VEO Accelerator is a six-module control room for video AI visibility.
<BR><BR>
Monitor every time your content gets cited by ChatGPT, Perplexity, Gemini, or Claude.
<BR><BR>
Generate one-click VideoObject schema engineered to be picked up and quoted by AI engines.
<BR><BR>
Find the exact queries where competitors get cited and you don''t — then ship the fix. Rewrite transcripts into citation-ready blocks. Track competitor channels eating your AI answer share.
<BR><BR>
Get a weekly intelligence report on your category''s AI visibility delivered to your inbox. Stop optimizing for last decade''s search. Start engineering for the engines actually answering your buyers.', NULL, 'https://veoaccelerator.com', '{"Video SEO","AI Citations","YouTube","Video Marketing"}', NULL, '{"VEO","video engine optimization","YouTube SEO","video AI visibility","video citations","VideoObject schema","AI video search","video transcripts","video optimization","YouTube AI","video content strategy","video schema markup","AI video citations","video search ranking","video content repurposing","video SEO tool","YouTube optimization","video AI search","transcript optimization","video structured data","citation tracking","competitor video analysis","video marketing","content creator tools","YouTube growth"}', '$0 to $197/month', 'https://lmpkwelyoiemyzdaiucd.supabase.co/storage/v1/object/public/tool-images/8c53a27d-6cd4-45af-ab05-5e048ff76b9d.png', true);
